#pragma once
#include <cstdint>
#if !defined(__arm__) && !defined(__thumb__)
#include <mutex>
#endif

namespace openosc {
// AXI SRAM on this MCU does not support the exclusive transactions generated by atomic RMW.
// A single-core interrupt mask protects these bounded control-state updates instead.
class CriticalSection {
public:
    CriticalSection() {
#if defined(__arm__) || defined(__thumb__)
        __asm volatile("mrs %0, primask\ncpsid i" : "=r"(previous_)::"memory");
#else
        mutex_.lock();
#endif
    }
    ~CriticalSection() {
#if defined(__arm__) || defined(__thumb__)
        __asm volatile("msr primask, %0" ::"r"(previous_) : "memory");
#else
        mutex_.unlock();
#endif
    }
    CriticalSection(const CriticalSection &) = delete;
    CriticalSection &operator=(const CriticalSection &) = delete;

private:
#if defined(__arm__) || defined(__thumb__)
    uint32_t previous_;
#else
    inline static std::recursive_mutex mutex_; // Match nested PRIMASK save/restore on the target.
#endif
};
} // namespace openosc
